// HOURLY: per module, sent in the last 60 minutes and today, split into basic (dull) / exciting, and how many of the exciting ones are NEW messages (owner 25 Nov: "so I know every hour how many are growing")
try {
    $src = ['cold' => ["SELECT tpl_id, SUM(at >= ?) h, COUNT(*) d FROM wa_cold_log WHERE ok = 1 AND at >= ? AND id > (SELECT MAX(id) - 150000 FROM wa_cold_log) GROUP BY tpl_id"],
        'B/C' => ["SELECT tpl_id, SUM(at >= ?) h, COUNT(*) d FROM wa_ru_log WHERE ok = 1 AND at >= ? AND id > (SELECT MAX(id) - 80000 FROM wa_ru_log) GROUP BY tpl_id"],
        'lineup' => ["SELECT tpl_id, SUM(sent_at >= ?) h, COUNT(*) d FROM wa_line_plan WHERE status = 'sent' AND sent_at >= ? AND id > (SELECT MAX(id) - 400000 FROM wa_line_plan) GROUP BY tpl_id"],
        'after' => ["SELECT tpl_id, SUM(sent_at >= ?) h, COUNT(*) d FROM wa_aft_plan WHERE status = 'sent' AND sent_at >= ? AND id > (SELECT MAX(id) - 300000 FROM wa_aft_plan) GROUP BY tpl_id"]];
    $h1 = date('Y-m-d H:i:s', time() - 3600); $tpl = []; $out = [];
    foreach ($src as $m => $q) { $rows = $one($q[0], [$h1, $t0]); $tot = ['dull_h' => 0, 'exc_h' => 0, 'new_h' => 0, 'dull_d' => 0, 'exc_d' => 0, 'new_d' => 0];
        foreach ($rows as $r) { if (!isset($r[2])) continue; $id = (int)$r[0]; if (!isset($tpl[$id])) { $x = $one("SELECT name, body, extra FROM wa_templates WHERE id = ?", [$id]); $tpl[$id] = $x[0] ?? ['', '', '']; }
            [$nm, $bd, $ex] = $tpl[$id]; $dull = function_exists('wa_rs_dull') ? wa_rs_dull((string)$bd) : (wa_style_dull((string)$bd) !== ''); $new = !$dull && (strpos((string)$ex, 'restyle_of') !== false || preg_match('/^(tmph_ord_|tmph_style_|tmph_new_|open_ex|ask_ex|order_ex|rs\d+_)/', (string)$nm));
            $tot[$dull ? 'dull_h' : 'exc_h'] += (int)$r[1]; $tot[$dull ? 'dull_d' : 'exc_d'] += (int)$r[2]; if ($new) { $tot['new_h'] += (int)$r[1]; $tot['new_d'] += (int)$r[2]; } }
        $out[$m] = $tot; }
    echo "ASK HOURLY (last 60 min | today) " . json_encode($out) . " · now " . date('H:i') . "\n";
} catch (Throwable $e) { echo "ASK HOURLY ERR " . substr($e->getMessage(), 0, 200) . "\n"; }
